-- Project K legends: 3 versions each (Macau foil, Chinese trial deck, English trial deck). New photos, English trial-deck cards added. Safe to run more than once.
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/loose-cannon-macau-holo-v2-ch-item-15.webp','inf',(data->>'inf') || $j$ The Macau silver-pack copy shows a rainbow holo shimmer across the whole card with the foil bubble pattern, and has no SAMPLE stamp.$j$) where id = 'item-15' and (data->>'inf') not like '%rainbow holo shimmer%';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/machine-herald-macau-holo-v2-ch-item-13.webp','inf',(data->>'inf') || $j$ The Macau silver-pack copy shows a rainbow holo shimmer across the whole card with the foil bubble pattern, and has no SAMPLE stamp.$j$) where id = 'item-13' and (data->>'inf') not like '%rainbow holo shimmer%';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/immortal-madness-macau-holo-v2-ch-item-14.webp','inf',(data->>'inf') || $j$ The Macau silver-pack copy shows a rainbow holo shimmer across the whole card with the foil bubble pattern, and has no SAMPLE stamp.$j$) where id = 'item-14' and (data->>'inf') not like '%rainbow holo shimmer%';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/gale-swordsman-macau-holo-v2-ch-item-16.webp','inf',(data->>'inf') || $j$ The Macau silver-pack copy shows a rainbow holo shimmer across the whole card with the foil bubble pattern, and has no SAMPLE stamp.$j$) where id = 'item-16' and (data->>'inf') not like '%rainbow holo shimmer%';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/loose-cannon-project-k-trial-deck-sample-v2-ch-item-10602.webp') where id = 'item-10602';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/machine-herald-project-k-trial-deck-sample-v2-ch-item-10600.webp') where id = 'item-10600';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/immortal-madness-project-k-trial-deck-sample-v2-ch-item-10601.webp') where id = 'item-10601';
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/gale-swordsman-project-k-trial-deck-sample-v2-ch-item-10603.webp') where id = 'item-10603';
insert into promo_items (id, r, data)
select 'item-10670', 10670, $j${"cat": "PROMO + COLLECTIBLE", "ra": "Legend", "do": "Fury\nChaos", "tg": "Legend\nJinx\nProject K\nSample", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "By itself", "cn": "251", "se": "FND", "r": 10670, "id": "item-10670", "nm": "Loose Cannon [Project K Trial Deck]", "la": "English", "ty": "Card", "ev": "Multiple Events/Cons global regions excluding China", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/loose-cannon-project-k-trial-deck-sample-en-item-10670.webp", "inf": "English-language Project K trial-deck version of this legend. These came inside the English Project K trial decks (Viktor, Jinx, Volibear, Yasuo) handed out in 2025 at events such as Gen Con, MSI in Vancouver and Geek Culture Retailer Day. Same card as the Chinese Macau silver-pack promo, but in English, non-foil and with SAMPLE printed across the front.\n\nGrading heads-up: PSA, Beckett and other graders don't label these consistently. The same card can come back titled Project K, Macau, Trial Deck, Sample or Alpha, and the two versions have been mixed up on slabs. Go by the card itself: the trial-deck copy has SAMPLE printed across the front, the Macau silver-pack copy is holo with no SAMPLE stamp.\n\nCounterfeits of early Project K cards circulate, so check the card in hand: trial-deck cards are non-foil with SAMPLE across the front."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10670');
insert into promo_items (id, r, data)
